package com.amdocs.telecom.service;import com.amdocs.telecom.util.DBConnection;import java.sql.*;public class EscalationService{public void escalate(long id,String from,String to,String reason,String actor)throws SQLException{try(Connection c=DBConnection.getInstance().get()){c.setAutoCommit(false);try(PreparedStatement p=c.prepareStatement("INSERT INTO escalation_history(ticket_id,from_level,to_level,reason,escalated_by)VALUES(?,?,?,?,?)")){p.setLong(1,id);p.setString(2,from);p.setString(3,to);p.setString(4,reason);p.setString(5,actor);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("UPDATE trouble_tickets SET status='ESCALATED',updated_at=CURRENT_TIMESTAMP WHERE ticket_id=?")){p.setLong(1,id);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("INSERT INTO ticket_status_history(ticket_id,old_status,new_status,changed_by,remarks) VALUES(?,'IN_PROGRESS','ESCALATED',?,?)")){p.setLong(1,id);p.setString(2,actor);p.setString(3,reason);p.executeUpdate();}c.commit();}}
}
